('00000000-0000-0000-0000-000000000000', 'Ist Vertraulichkeit ein Schutzziele des IT-Grundschutzes im Anwendersupport?', 2, '[{"text": "Ja", "correct": true, "because": "Schutz sensibler Daten"}, {"text": "Nein", "correct": false, "because": "Kernziel des Grundschutzes"}]'),
('00000000-0000-0000-0000-000000000000', 'Gehört Verfügbarkeit zu den Schutzziele des IT-Grundschutzes im Anwendersupport?', 2, '[{"text": "Ja", "correct": true, "because": "Sicherstellung des Zugriffs"}, {"text": "Nein", "correct": false, "because": "Grundschutzziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist Integrität ein Schutzziele des IT-Grundschutzes im Anwendersupport?', 2, '[{"text": "Ja", "correct": true, "because": "Daten unverändert halten"}, {"text": "Nein", "correct": false, "because": "Teil des Grundschutzes"}]'),
