-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Schutzziele des IT-Grundschutzes schützt vor unbefugtem Zugriff im Anwendersupport?', 2, '[{"text": "Vertraulichkeit", "correct": true, "because": "Zugriff einschränken"}, {"text": "Integrität", "correct": false, "because": "Datenänderung"}, {"text": "Verfügbarkeit", "correct": false, "because": "Zugriff gewährleisten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Schutzziele stellt sicher, dass Daten im Anwendersupport korrekt bleiben?', 3, '[{"text": "Integrität", "correct": true, "because": "Daten unverfälscht"}, {"text": "Vertraulichkeit", "correct": false, "because": "Zugriffsschutz"}, {"text": "Verfügbarkeit", "correct": false, "because": "Nutzungssicherung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Schutzziele des IT-Grundschutzes gewährleistet Systemzugriff im Anwendersupport?', 2, '[{"text": "Verfügbarkeit", "correct": true, "because": "Systeme nutzbar halten"}, {"text": "Integrität", "correct": false, "because": "Datenkorrektheit"}, {"text": "Vertraulichkeit", "correct": false, "because": "Datenschutz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Schutzziele wird im Anwendersupport durch Verschlüsselung unterstützt?', 2, '[{"text": "Vertraulichkeit", "correct": true, "because": "Daten verschlüsseln"}, {"text": "Verfügbarkeit", "correct": false, "because": "Zugriffssicherung"}, {"text": "Integrität", "correct": false, "because": "Datenintegrität"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Schutzziele schützt im Anwendersupport vor Datenmanipulation?', 2, '[{"text": "Integrität", "correct": true, "because": "Daten unverändert"}, {"text": "Vertraulichkeit", "correct": false, "because": "Zugriffsschutz"}, {"text": "Verfügbarkeit", "correct": false, "because": "Nutzungssicherung"}]'),

-- Multiple-Choice-Fragen (5 Stück)
