('00000000-0000-0000-0000-000000000000', 'Welche Schutzziele des IT-Grundschutzes sind im Anwendersupport relevant?', 4, '[{"text": "Vertraulichkeit", "correct": true, "because": "Schutz sensibler Daten"}, {"text": "Integrität", "correct": true, "because": "Datenintegrität"}, {"text": "Verfügbarkeit", "correct": true, "because": "Systemzugriff"}, {"text": "Benutzerfreundlichkeit", "correct": false, "because": "Kein Schutzziele"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Beispiele zeigen Schutzziele des IT-Grundschutzes im Anwendersupport?', 3, '[{"text": "Passwortschutz", "correct": true, "because": "Vertraulichkeit"}, {"text": "Datenprüfung", "correct": true, "because": "Integrität"}, {"text": "Redundante Server", "correct": true, "because": "Verfügbarkeit"}, {"text": "Schnelle Antwortzeit", "correct": false, "because": "Kein Schutzziele"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Vertraulichkeit schützt vor unbefugtem Zugriff im Anwendersupport. b) Integrität stellt Systemverfügbarkeit sicher.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Vertraulichkeit ja, Integrität anders"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Verfügbarkeit ist ein Schutzziele des IT-Grundschutzes. b) Schutzziele betreffen nur Software.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Verfügbarkeit ja, auch Hardware"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Integrität schützt vor Datenmanipulation im Anwendersupport. b) Vertraulichkeit sorgt für Datenverfügbarkeit.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Integrität ja, Vertraulichkeit anders"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Schutzziele des IT-Grundschutzes sind im Anwendersupport unverzichtbar. b) Verfügbarkeit ist kein Schutzziele.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Unverzichtbar ja, Verfügbarkeit Ziel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Backups unterstützen Verfügbarkeit im Anwendersupport. b) Integrität schützt vor unbefugtem Zugriff.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Backups ja, Integrität anders"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

